                        parent : opt.body,
                        type : "group",
                    });
                    await $c.comp.create({
                        parent : row,
                        type : "trigger",
                        text : "setRowData",
						click : function(){
							$c.grid.setRowData({data : {PARENT_SAMPLE_CD : 1, SAMPLE_LEVEL : 2}});
						},
                    });
                    await $c.comp.create({
                        parent : row,
                        type : "trigger",
                        text : "getRowData",
						click : function(){
							console.log("getRowData", $c.grid.getRowData());
						},
                    });
                    var row = await $c.comp.create({
                        parent : opt.body,
                        type : "group",
                    });
                    await $c.comp.create({
                        parent : row,
                        type : "trigger",
                        text : "insertLocalStorage",
						click : function(){
							$c.cmm.insertLocalStorage({key : "test", data : {a : 1}});
                            console.log("insertLocalStorage", $c.cmm.selectLocalStorage({key : "test"}));
